import re
import time

from ute_ue.data_transfers.lte_data_transfer import LteDataTransfer
from ute_ue.exceptions import DataTransferMissingArguments

from ...exceptions import HostNotReachableError, UnexpectedCmdResultException
from ...utils.ssh_manager import SshManager
from ...utils.utils import Utils
from ..data_transfer_utilities import get_at_ue_ip
from ..icmp import ping_options


class AtDataTransferIcmp(LteDataTransfer):

    def __init__(self, name, ue_pc, com_port, dt_definition, configuration, logger_name='ute_ue'):
        """
        :param name: alias of data transfer
        :param ue_pc: Rpc object responsible for HTTP/HTTPS request
        :param com_port: UE com port
        :param dt_definition: object containing data transfer's details
        :param configuration: UE configuration from config yaml file
        """
        super().__init__(name, dt_definition, configuration, logger_name)
        self.utils = Utils()
        self.dt_config = self._build_dt_config(dt_definition, configuration)
        self.is_dt_running = False
        self.is_direction_downlink = self.dt_config['direction'] == "dl"
        self.ue_pc = ue_pc
        self.com_port = com_port
        self._ue_ip = ''
        self.dt_id = f"{self.dt_config['direction']}_{self.dt_config['protocol']}_p{self.dt_config['port']}"
        self.result = None
        self._is_running = False
        self.success_started = False
        self.ssh_manager = None
        self.downlink_ssh_reader = None
        self.ping_cmd = None
        self.logger.debug(f"{self.name} created with configuration: {self.dt_config}")

    def start(self):
        """
        Starts data transfer with parameters defined in dt_definition passed during initialization.
        :return: None
        """
        self.logger.debug(f"{self.name} call: starting ping data transfer")
        self._is_running = True
        access_prefix = (self._configuration.get("sub_access", "At") or "At").capitalize()
        self.dt_id = f"{self.dt_config['direction']}_{self.dt_config['protocol']}_p{self.dt_config['port']}"
        self.ue_ip = get_at_ue_ip(ue_pc=self.ue_pc, ue_id=self.com_port, logger=self.logger)
        if self.is_direction_downlink:
            ip_to_ping = self._get_ip_to_ping_from_ue()
        else:
            dt_class = f"{access_prefix}UePing"
            ip_to_ping = self._get_app_server_ip()
        ue_ping_cmd = self._get_ping_cmd(ip_to_ping)
        ping_cmd_timeout = self.dt_config["duration"] + 5
        if self.is_direction_downlink:
            self.ping_ue(ue_ip=ip_to_ping)
        else:
            self.ue_pc.start_data_transfer(ue_id=self.com_port,
                                           data_transfer_config={
                                               'data_transfer_cmd': ue_ping_cmd,
                                               'timeout': ping_cmd_timeout,
                                               'ue_pc': {
                                                   'host': self.dt_config['ue_pc_host'],
                                                   'login': self.dt_config['ue_pc_login'],
                                                   'password': self.dt_config['ue_pc_password']
                                               }
                                           },
                                           data_transfer_id=self.dt_id,
                                           data_transfer_class=dt_class)
        time.sleep(2)
        self.success_started = True
        self.logger.debug(f"{self.name}: ping data transfer successfully started!")

    def ping_ue(self, ue_ip):
        """Ping UE from app server"""
        app_server_ip = self._get_app_server_ip()
        self._ue_ip = ue_ip
        self.ping_cmd = self._get_ping_cmd(ip_to_ping=ue_ip)
        ssh = self._create_ssh_manager_and_register_host(self.dt_config['app_server'])
        self.logger.debug(f'{self.name}: triggering ping App Server ({app_server_ip}) --> ({self._ue_ip}) UE "'
                          f'f"{self.ping_cmd}.',
                          extra={'ue_id': ""})
        self.downlink_ssh_reader = ssh.run_cmd_and_get_non_blocking_reader(self.ping_cmd, app_server_ip)

    def _get_app_server_bind_ip(self):
        bind_ip = self.dt_config['app_server'].get('bind_interface_ip')
        if not isinstance(bind_ip, str) or not bind_ip:
            raise ValueError("bind_interface_ip must be a non-empty string and always be specified during DT execution")
        return bind_ip

    def _get_app_server_ip(self):
        address = self.dt_config['app_server'].get('address')
        if not isinstance(address, str) or not address:
            raise ValueError("address must be a non-empty string and always be specified")
        return address

    def _create_ssh_manager_and_register_host(self, app_server):
        self.logger.debug(f"{self.name}: creating ssh manager for downlink ping data transfer")
        self.ssh_manager = SshManager()
        self.ssh_manager.register(app_server['address'], app_server['user'], app_server['password'])
        return self.ssh_manager

    def _get_ip_to_ping_from_ue(self):
        """Returns ip that UE will ping: any ping_host_ip if is given or app server ip"""
        if 'address' in self.dt_config and self.dt_config['address'] is not None:
            return self.dt_config['address']
        if 'address' in self.dt_config['app_server']:
            return self._get_icmp_connection_ip()
        raise DataTransferMissingArguments("Please provide IP for ping. Possible entries are:\n"
                                           "- `address` robot keyword argument\n"
                                           "- `address` at data_transfer['ping'] yaml section\n"
                                           "- `address` for app_server")

    def _get_icmp_connection_ip(self):
        bind_ip = self._get_app_server_bind_ip()
        address = self._get_app_server_ip()
        return bind_ip or address

    def _get_ping_cmd(self, ip_to_ping):
        options_to_search = \
            ping_options.PING_OPTIONS_DOWNLINK if self.is_direction_downlink else ping_options.PING_OPTIONS_UPLINK
        ping_arguments = ['ping6' if get_ip_version(ip_to_ping) == 6 else 'ping']
        for option_name, attr_symbol in options_to_search.items():
            if option_name in self.dt_config and self.dt_config[option_name] is not None:
                ping_parameter = f'-{attr_symbol} {self.dt_config[option_name]}'
                ping_arguments.append(ping_parameter)
        ping_arguments.append(ip_to_ping)
        ping_cmd = ' '.join(ping_arguments)
        self.logger.debug(f'{self.name} ping command: {ping_cmd}')
        return ping_cmd

    def is_running(self):
        """
        Check if data transfer is running

        :return: boolean
        """
        if self._is_running:
            self.logger.debug(f"{self.name} is still running: {self._is_running}")
        return self._is_running

    def stop(self):
        """
        Stop ICMP data transfer by killing ping command
        :return:
        """
        raise NotImplementedError("There is no option to stop FTP transfer from NAA."
                                  "Please, contact the development team if you need such possibility.")

    def check_data_transfer(self):
        """Not implemented"""
        raise NotImplementedError

    def reset_statistics(self):
        """Not implemented"""
        raise NotImplementedError

    def get_average_throughput(self, **kwargs):
        """
        Get average throughput of the data transfer.

        :return: int: Packet pass ratio (in %).
        """
        timeout = kwargs.get('timeout', 30)
        self.logger.debug(f'{self.name} call: get average throughput')
        if self.is_direction_downlink:
            self.result = self.utils.get_non_blocking_reader_result(self.downlink_ssh_reader,
                                                                    timeout=timeout,
                                                                    interval=self.dt_config['interval'])
            average_throughput = self._verify_ping_output(self.result, allowed_packet_loss=timeout)
        else:
            self.result = self.ue_pc.get_data_transfer_output(ue_id=self.com_port, data_transfer_id=self.dt_id)
            average_throughput = self.result['avg_throughput']
        self.logger.debug(f"{self.name}: average_throughput = {average_throughput}")
        return 100-average_throughput

    def get_datagram_loss(self):
        """Not implemented"""
        raise NotImplementedError

    @staticmethod
    def _raise_if_output_is_empty(ping_output):
        if not ping_output or len(ping_output) == 0:
            raise UnexpectedCmdResultException('Ping output is empty!')

    def _verify_ping_output(self, ping_output, allowed_packet_loss):
        self._raise_if_output_is_empty(ping_output)
        return self._verify_packet_loss(ping_output, allowed_packet_loss)

    def _verify_packet_loss(self, ping_output, allowed_packet_loss):
        ping_output = "".join(ping_output)
        packet_loss = int(self._get_value_from_ping_output('packet_loss', ping_output))
        if packet_loss == 100:
            raise HostNotReachableError("Packet loss 100%")
        return packet_loss

    @staticmethod
    def _get_value_from_ping_output(stats_name, ping_output):
        stats_regex = ping_options.PING_STATS_REGEX[stats_name]
        match = re.search(stats_regex, ping_output)
        if not match:
            raise ValueError(f'Unable to find {stats_name} in ping output:\n{ping_output}')
        result = match.groups()
        value = result[0]
        return value

    def _build_dt_config(self, dt_definition, configuration):
        dt_config = {
            'app_server': configuration['data_transfer']['ping']['app_server'],
            'interface_name': configuration['data_transfer']['ping']['interface_name'],
            'app_server_bind_interface_ip':
                configuration['data_transfer']['ping']['app_server'].get('bind_interface_ip', None),
            'ue_pc_host': configuration['ue_pc_address'],
            'ue_pc_login': configuration['ue_pc_login'],
            'ue_pc_password': configuration['ue_pc_password'],
            'protocol': dt_definition.protocol,
            'ping_count': ping_options.DEFAULT_PING_COUNT,
            'duration': dt_definition.duration if dt_definition.duration != 863913600.0 else 86400.0,
            'throughput': dt_definition.throughput,
            'direction': dt_definition.direction,
            'port': dt_definition.protocol_details.get('port', None),
            'interval': configuration['data_transfer']['ping'].get('interval', 1),
            'apn': dt_definition.protocol_details.get('apn', None),
            'allowed_packet_loss': 0,
        }
        if dt_config['app_server_bind_interface_ip']:
            dt_config['app_server_bind_interface_ip'] = dt_config['app_server_bind_interface_ip'].strip()
        self.port = dt_config.get("port")
        self.logger.debug(f"dt_config: {dt_config}")
        return dt_config


def get_ip_version(address=""):
    """Trival method to get ip version from ip string"""
    if ":" in address:
        return 6
    return 4
